cat > /tmp/fix_pretty.py << 'ENDOFFILE'
import sys

# Read the file
with open('/testbed/sympy/printing/pretty/pretty.py', 'r') as f:
    content = f.read()

# Find and replace the _print_MatAdd method with a simpler version
old_method = '''    def _print_MatAdd(self, expr):
        from sympy import Mul
        PREC = precedence(expr)
        pforms = []
        for i, arg in enumerate(expr.args):
            if hasattr(arg, 'as_coeff_matrices'):
                coeff, matrices = arg.as_coeff_matrices()
                if coeff < 0:
                    matrices = [Mul(-coeff, *matrices, evaluate=False)]
                    pform = self._print_seq(matrices, None, None, '*')
                    if i == 0:
                        pform = prettyForm('-', pform)
                    else:
                        pform = prettyForm(' - ', pform)
                else:
                    pform = self._print_seq(matrices, None, None, '*')
                    if i == 0:
                        pass
                    else:
                        pform = prettyForm(' + ', pform)
            else:
                pform = self._print(arg)
                if i == 0:
                    if str(pform).startswith('-'):
                        pform = prettyForm('-', pform[1:])
                else:
                    if str(pform).startswith('-'):
                        pform = prettyForm(' - ', pform[1:])
                    else:
                        pform = prettyForm(' + ', pform)
            pforms.append(pform)
        return prettyForm.__add__(*pforms)'''

new_method = '''    def _print_MatAdd(self, expr):
        from sympy import Mul
        PREC = precedence(expr)
        pforms = []
        for i, arg in enumerate(expr.args):
            if hasattr(arg, 'as_coeff_matrices'):
                coeff, matrices = arg.as_coeff_matrices()
                if coeff < 0:
                    matrices = [Mul(-coeff, *matrices, evaluate=False)]
                    pform = self._print_seq(matrices, None, None, '*')
                    if i == 0:
                        pform = prettyForm('-', pform)
                    else:
                        pform = prettyForm(' - ', pform)
                else:
                    pform = self._print_seq(matrices, None, None, '*')
                    if i == 0:
                        pass
                    else:
                        pform = prettyForm(' + ', pform)
            else:
                pform = self._print(arg)
                if i == 0:
                    if str(pform).startswith('-'):
                        pform = prettyForm('-', pform[1:])
                else:
                    if str(pform).startswith('-'):
                        pform = prettyForm(' - ', pform[1:])
                    else:
                        pform = prettyForm(' + ', pform)
            pforms.append(pform)
        return prettyForm.__add__(*pforms)'''

if old_method in content:
    content = content.replace(old_method, new_method)
    with open('/testbed/sympy/printing/pretty/pretty.py', 'w') as f:
        f.write(content)
    print("Successfully updated pretty.py")
else:
    print("Could not find the method to replace")
    sys.exit(1)
